def main():
    batch2 = json.loads((DIR / "_apps-batch-2.json").read_text("utf-8"))
    have = json.loads((DIR / "_batch2-have.json").read_text("utf-8"))
    have_map = {row[0]: row for row in have}
    gen_map = {row[0]: row for row in GEN}

    rows = []
    missing = []
    for en in batch2:
        if en in have_map:
            rows.append(have_map[en])
        elif en in gen_map:
            rows.append(gen_map[en])
        else:
            missing.append(en)

    if missing:
        raise SystemExit(f"Missing translations for {len(missing)} strings: {missing[:5]}")

    if len(rows) != 155:
        raise SystemExit(f"Expected 155 rows, got {len(rows)}")

    for i, row in enumerate(rows):
        if len(row) != 10:
            raise SystemExit(f"Row {i+1} has {len(row)} cols: {row[0]!r}")
        if row[0] != batch2[i]:
            raise SystemExit(f"Order mismatch at {i}: {row[0]!r} != {batch2[i]!r}")

    out_lines = ["export const APPS_RAW_BATCH2 = ["]
    for row in rows:
        out_lines.append("  " + json.dumps(row, ensure_ascii=False) + ",")
    out_lines.append("];")
    out_lines.append("")

    out_path = DIR / "i18n-apps-phrases-batch2.mjs"
    out_path.write_text("\n".join(out_lines), encoding="utf-8")
    print(f"Wrote {len(rows)} rows to {out_path.name}")

if __name__ == "__main__":
    main()
